import type { Address } from 'abitype'
import * as RpcResponse from 'ox/RpcResponse'
import { call } from '../../../actions/public/call.js'
import type { Client } from '../../../clients/createClient.js'
import { decodeAbiParameters } from '../../../utils/abi/decodeAbiParameters.js'
import { decodeFunctionResult } from '../../../utils/abi/decodeFunctionResult.js'
import { encodeAbiParameters } from '../../../utils/abi/encodeAbiParameters.js'
import { encodeFunctionData } from '../../../utils/abi/encodeFunctionData.js'
import { concat } from '../../../utils/data/concat.js'
import * as Abis from '../../Abis.js'
import * as Addresses from '../../Addresses.js'
import type * as Funding from '../../actions/funding.js'

/** Reads access-key metadata and the selected policy at the same block. */
export async function preflight(
  client: Client,
  options: {
    account: Address
    keyId: Address
    policyId: bigint
  },
) {
  const { data } = await call(client, {
    batch: false,
    gas: 16_000_000n,
    data: concat([
      preflightBytecode,
      encodeAbiParameters(
        [
          { type: 'address' },
          { type: 'address' },
          { type: 'address' },
          { type: 'address' },
          { type: 'uint64' },
        ],
        [
          Addresses.accountKeychain,
          Addresses.fundingPolicy,
          options.account,
          options.keyId,
          options.policyId,
        ],
      ),
    ]),
  })
  const [blockNumber, timestamp, metadata, policyId, rulesHash] =
    decodeAbiParameters(
      [
        { type: 'uint256' },
        { type: 'uint256' },
        { type: 'bytes' },
        { type: 'uint64' },
        { type: 'bytes32' },
      ],
      data ?? '0x',
    )
  return {
    blockNumber,
    timestamp,
    policyId,
    rulesHash,
    metadata: decodeFunctionResult({
      abi: Abis.accountKeychain,
      functionName: 'getKey',
      data: metadata,
    }),
  }
}

/** Batches route discovery without changing the account inspected by each source. */
export async function discover(
  client: Client,
  requirements: readonly Extract<Funding.discover.Args, { sources: unknown }>[],
) {
  if (requirements.length === 0) return []
  if (requirements.length > 64)
    throw new RpcResponse.InvalidParamsError({
      message: 'Funding discovery supports at most 64 output requirements.',
    })
  const calls = requirements.map((requirement) =>
    encodeFunctionData({
      abi: [Abis.fundingDiscovery[0]],
      functionName: 'discover',
      args: [
        requirement.account,
        requirement.token,
        requirement.amount,
        requirement.slippageBps,
        requirement.sources.map(({ target, data }) => ({ target, data })),
      ],
    }),
  )
  const data = concat([
    discoveryBytecode,
    encodeAbiParameters(
      [{ type: 'address' }, { type: 'bytes[]' }],
      [Addresses.fundingDiscovery, calls],
    ),
  ])
  if (data.length > 2 + 131072 * 2)
    throw new RpcResponse.InvalidParamsError({
      message: 'Funding discovery calldata exceeds 128 KiB.',
    })
  const result = await call(client, { batch: false, gas: 16_000_000n, data })
  const [results] = decodeAbiParameters(
    [{ type: 'bytes[]' }],
    result.data ?? '0x',
  )
  return results.map((data) =>
    decodeFunctionResult({
      abi: [Abis.fundingDiscovery[0]],
      functionName: 'discover',
      data,
    }),
  )
}

// forge inspect --config-path contracts/foundry.toml src/deployless/FundingRead.sol:FundingPreflight bytecode --optimize --evm-version paris
const preflightBytecode =
  ''

// forge inspect --config-path contracts/foundry.toml src/deployless/FundingRead.sol:FundingDiscover bytecode --optimize --evm-version paris
const discoveryBytecode =
  ''
